import{_ as e,o as a,c as n,a3 as i}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"Simulation, replay, and validation","description":"Map each validation level to what it can and cannot establish for autonomous-driving claims.","frontmatter":{"title":"Simulation, replay, and validation","description":"Map each validation level to what it can and cannot establish for autonomous-driving claims.","content_type":"knowledge","status":"design guidance","scope":"verification and validation strategy","keywords":["simulation","replay","SIL","HIL","closed course","safety case"],"evidence_ids":[]},"headers":[],"relativePath":"en/knowledge/validation.md","filePath":"en/knowledge/validation.md","lastUpdated":1794216847000}'),o={name:"en/knowledge/validation.md"};function d(r,t,s,l,c,p){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="simulation-replay-and-validation" tabindex="-1">Simulation, replay, and validation <a class="header-anchor" href="#simulation-replay-and-validation" aria-label="Permalink to &quot;Simulation, replay, and validation&quot;">​</a></h1><p><strong>Status:</strong> <code>design guidance</code></p><p>Validation claims must state the evidence level:</p><table tabindex="0"><thead><tr><th>Level</th><th>Can establish</th><th>Cannot establish</th></tr></thead><tbody><tr><td>Unit/interface test</td><td>Data structures and local logic</td><td>System real-time behavior or safety</td></tr><tr><td>Offline replay</td><td>Repeatability under fixed data and configuration</td><td>Online clocks, drivers, and actuators</td></tr><tr><td>Simulation/SIL</td><td>Scenario behavior and interface integration</td><td>Real sensor noise, chassis dynamics, road risk</td></tr><tr><td>HIL</td><td>Hardware/software timing and interfaces under lab conditions</td><td>Unmodeled site hazards and full vehicle behavior</td></tr><tr><td>Closed course</td><td>Named vehicle and scenario performance</td><td>Uncovered sites, production safety</td></tr><tr><td>Controlled operation/public road/production</td><td>Evidence under an approved operating scope</td><td>Generalization to other vehicles or regulations</td></tr></tbody></table><p>Every experiment should retain versions, configuration, scenario definition, random seed, data provenance, metrics, failure samples, and the exact boundary of its conclusion.</p><p>Simulation, replay, and closed-course success are cumulative evidence, not substitutes for one another.</p><p>Safety-related projects should also use <a href="https://www.iso.org/standard/68383.html" target="_blank" rel="noreferrer">ISO 26262</a> functional safety, <a href="https://www.iso.org/standard/77490.html" target="_blank" rel="noreferrer">ISO 21448</a> SOTIF, and UL 4600 safety-case methods as reference frameworks. Referencing these standards does not mean that a WheelOS product or this repository is certified.</p>',7)])])}const f=e(o,[["render",d]]);export{h as __pageData,f as default};
